const e=[{id:"sv-2-741",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"Where was FMEA first used, according to the book?",options:["In the Toyota Production System in the 1950s","In Motorola's quality programme in the 1980s","In the AIAG automotive standard in the 1990s","On the Apollo space missions in the 1960s"],answer:3,hint:"Recall the first line of the book's FMEA history.",steps:[{title:"Key idea",body:"The book's history (p. 124) starts in aerospace: FMEA was first used in the **1960s on the Apollo missions**."},{title:"Eliminate look-alikes",body:"Toyota is Lean's origin, Motorola is Six Sigma's, and the AIAG is the current custodian of the standard."}],final:"First use = Apollo, 1960s → answer **D**",whyWrong:["Incorrect — the Toyota Production System is the origin of Lean tools such as Kanban, not FMEA.","Incorrect — Motorola is the origin of Six Sigma; FMEA was already decades old by then.","Incorrect — the AIAG maintains today's FMEA standard; it did not create the method.",""],bookRef:"Book p. 124"},{id:"sv-2-742",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"What is a **System FMEA** used to analyse?",options:["Failure modes of a product design before it is released","Failure modes in a manufacturing or transactional process","Failure modes of the equipment used to make or test the product","Failures at the early concept level, where modules tie together into a system"],answer:3,hint:"Each of the four FMEA types is named after what it studies.",steps:[{title:"Key idea",body:"Book types (p. 124): **System** (early concept, modules tied together), Design (product before release), Process (manufacturing and transactional), Equipment (machines that make or test)."},{title:"Apply to the stem",body:"Only the System FMEA works at the concept level where modules connect, e.g. a car's electrical system."}],final:"System FMEA = concept level, modules tied together → answer **D**",whyWrong:["Incorrect — this describes a Design FMEA (DFMEA).","Incorrect — this describes a Process FMEA (PFMEA).","Incorrect — this describes an Equipment FMEA.",""],bookRef:"Book p. 124"},{id:"sv-2-743",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"How do FMEAs manage risk, according to the book?",options:["By removing every possible X from the process","By proving each X with a hypothesis test","By calculating the capability of every process step","By classifying inputs and monitoring their effects"],answer:3,hint:"Recall the book's one-line description of how an FMEA handles risk.",steps:[{title:"Key idea",body:"The book (p. 126): FMEAs manage **risk** by **classifying inputs** and **monitoring their effects**."},{title:"Eliminate look-alikes",body:"Elimination, proof and capability calculation are other tools' jobs."}],final:"Classify inputs, monitor effects → answer **D**",whyWrong:["Incorrect — the book says the FMEA controls X's; it does not eliminate them.","Incorrect — statistical proof of X's happens in Analyze, not inside the FMEA.","Incorrect — capability studies feed the occurrence rating; they are not how the FMEA manages risk.",""],bookRef:"Book p. 126"},{id:"sv-2-744",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"Which type of FMEA does a Black Belt use most often?",options:["Design FMEA","Equipment FMEA","Process FMEA","System FMEA"],answer:2,hint:"DMAIC projects improve existing processes.",steps:[{title:"Key idea",body:"A PFMEA studies how manufacturing **and transactional** processes can fail and let defects escape to the customer."},{title:"Apply to the stem",body:"Green Belt projects improve running processes, so the PFMEA is the type used most."}],final:"Process FMEA → answer **C**",whyWrong:["Incorrect — a Design FMEA studies a product design before release, which is less common in DMAIC projects.","Incorrect — an Equipment FMEA covers machines and test sets only.","","Incorrect — a System FMEA works at early concept level, not on a running process."],bookRef:"Book p. 124"},{id:"sv-2-745",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"According to the book, when should a process FMEA first be started?",options:["After the first customer complaint","In the Control phase, once solutions are in place","After the capability study is complete","At the conceptual design stage"],answer:3,hint:"FMEA is about predicting failures, so it starts early.",steps:[{title:"Key idea",body:"The book (p. 125): a PFMEA starts at the **conceptual design** stage and is updated as the process changes."},{title:"Eliminate look-alikes",body:"Waiting for complaints, capability data or Control defeats its purpose of prevention."}],final:"Start at conceptual design → answer **D**",whyWrong:["Incorrect — the FMEA is a prevention tool; it is not meant to wait for a failure.","Incorrect — in Control the FMEA is updated and used; it should already exist.","Incorrect — capability results refine occurrence ratings later; they are not a starting condition.",""],bookRef:"Book p. 125"},{id:"sv-2-746",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"What does the Control-phase checklist ask the team to show from its FMEA?",options:["That every RPN is now below 100","Improvement in RPN through the action items","That severity has fallen for each failure mode","That the FMEA has been closed and archived"],answer:1,hint:"The checklist links the actions to a change in risk.",steps:[{title:"Key idea",body:"The Control checklist asks the team to **show improvement in RPN through action items**, with revised occurrence and controls."},{title:"Eliminate look-alikes",body:"There is no fixed RPN target, severity rarely changes, and the FMEA is never archived as finished."}],final:"Show RPN improvement through actions → answer **B**",whyWrong:["Incorrect — the book sets no universal RPN threshold such as 100.","","Incorrect — severity normally stays the same; actions lower occurrence or detection.","Incorrect — the FMEA is a living document handed on, not closed."],bookRef:"Book pp. 135, 570"},{id:"sv-2-747",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:"Why should an RPN of **200** not be read as twice as risky as an RPN of **100**?",options:["The RPN is found by adding the three ratings, not multiplying them","Severity, occurrence and detection are ordinal rankings, not measurements","The detection scale is inverted, so the RPN must be reversed first","The RPN can never be higher than 100, so 200 is a scoring error"],answer:1,hint:"Ask what kind of numbers S, O and D are.",steps:[{title:"Key idea",body:"S, O and D are 1–10 **rankings** (ordinal). Multiplying ranks gives an order, not a true ratio."},{title:"Apply to the stem",body:"An RPN of 200 ranks above 100, but it is not 'twice' the risk."}],final:"Ordinal scores → no ratio meaning → answer **B**",whyWrong:["Incorrect — the RPN is the product S × O × D.","","Incorrect — the inverted wording of the detection scale is already built into the ratings; nothing is reversed.","Incorrect — with three 1–10 ratings the RPN runs from 1 to 1,000."],bookRef:"Book pp. 129–135",trap:"Use RPN to rank, not to measure."},{id:"sv-2-748",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"What does a **Design FMEA** analyse?",options:["Failure modes of a running transactional process","Failure modes of the machines that test the product","Failure modes of a product before it is released","Failures where modules first tie together at concept level"],answer:2,hint:"Design = before release.",steps:[{title:"Key idea",body:"A DFMEA analyses **product failure modes before release** (book p. 124)."},{title:"Eliminate look-alikes",body:"Process, Equipment and System FMEAs each study something else."}],final:"DFMEA = product, before release → answer **C**",whyWrong:["Incorrect — a running process is the subject of a Process FMEA.","Incorrect — machines that make or test the product are covered by an Equipment FMEA.","","Incorrect — the concept level where modules tie together is a System FMEA."],bookRef:"Book p. 124"},{id:"sv-2-749",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"What does the **Actions taken** column of an FMEA record?",options:["The action the team recommends for the future","The control that is already in place today","The RPN threshold for taking action","What was actually done and the date it took effect"],answer:3,hint:"Recommended → owner and date → taken → re-scored.",steps:[{title:"Key idea",body:"The template ends: recommended actions, responsible person and target date, **actions taken (what was done and when)**, then new S, O, D and RPN."},{title:"Apply to the stem",body:"'Taken' means completed, not planned."}],final:"Actions taken = what was done, when → answer **D**",whyWrong:["Incorrect — the recommendation goes in the Recommended actions column.","Incorrect — today's control goes in the Current process controls column.","Incorrect — the book's template has no RPN-threshold column.",""],bookRef:"Book p. 135"},{id:"sv-2-750",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:'Which statement about an RPN rule such as "act on anything above 100" is CORRECT?',options:["It is a local convention, so ranking and judgement still decide priorities","It is fixed by the AIAG standard for every FMEA","It means failure modes below 100 never need action","It removes the need to look at severity separately"],answer:0,hint:"Is there a magic RPN number?",steps:[{title:"Key idea",body:"RPN thresholds are organisational conventions, not part of any standard."},{title:"Apply to the stem",body:"Teams rank by RPN and still act on very high severities, whatever the cut-off."}],final:"Thresholds are local; judgement still applies → answer **A**",whyWrong:["","Incorrect — no standard fixes a universal RPN cut-off; thresholds are set locally.","Incorrect — a very high severity can need action even with a low RPN.","Incorrect — severity is still reviewed on its own, because low O and D can hide a catastrophic effect."],bookRef:"Book p. 135"},{id:"sv-2-751",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"Which statement about the history of FMEA is CORRECT?",options:["It was created by Toyota as part of the Toyota Production System","It was used in aerospace and by the military before the car industry adopted it","It was invented by Motorola as a step in DMAIC","It was developed by the AIAG for the Apollo missions"],answer:1,hint:"Aerospace → military → automotive.",steps:[{title:"Key idea",body:"Book p. 124: Apollo (1960s) → US Navy MIL-STD-1629 (1974) → car industry (late 1970s) → AIAG maintains the standard."},{title:"Eliminate look-alikes",body:"Toyota, Motorola and an AIAG origin are all wrong attributions."}],final:"Aerospace and military first, then automotive → answer **B**",whyWrong:["Incorrect — Toyota is linked to Lean tools, not to the origin of FMEA.","","Incorrect — Motorola created Six Sigma; FMEA was already in use for decades.","Incorrect — Apollo used FMEA in the 1960s; the AIAG maintains the standard much later."],bookRef:"Book p. 124"},{id:"sv-2-752",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:"Which statement about re-scoring an FMEA after improvement is CORRECT?",options:["A planned action can be scored as complete to show progress to the Champion","Re-scoring should lower all three ratings for every failure mode","A new check earns a lower detection score only once it is proven to catch the failure","Severity should be lowered whenever a detection control is added"],answer:2,hint:"Re-scores need evidence.",steps:[{title:"Key idea",body:"The book places re-scoring after the action is **taken**; a lower score must be earned with evidence."},{title:"Eliminate look-alikes",body:"Planned actions, blanket reductions and lower severity from inspection are not credible re-scores."}],final:"Evidence-based re-score → answer **C**",whyWrong:["Incorrect — re-scoring happens after the action has actually been taken.","Incorrect — actions normally lower occurrence or detection; severity usually stays the same.","","Incorrect — a detection control changes DET; severity changes only with a design change."],bookRef:"Book p. 135"},{id:"sv-2-753",phase:2,topic:"2.1.4",qtype:"statements",difficulty:3,stem:`Which statements about the types of FMEA are CORRECT?

1. A Process FMEA can only be used in manufacturing.
2. An Equipment FMEA analyses the steps of a service process.
3. A System FMEA works at the early concept level, where modules tie together.
4. The severity rating from a Design FMEA must be carried into the Process FMEA.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Recall what each of the four types studies.",steps:[{title:"Key idea",body:"System = concept level; Design = product before release (severity carried into the PFMEA); Process = manufacturing **and** transactional; Equipment = machines that make or test."},{title:"Apply to the stem",body:"Statements 3 and 4 are true."}],final:"3 and 4 → answer **C**",whyWrong:["Incorrect — both are false: PFMEAs also cover transactional processes, and an Equipment FMEA covers machines.","Incorrect — statement 3 is true, but an Equipment FMEA studies equipment, not service steps.","","Incorrect — statement 4 is true, but PFMEAs are used for transactional as well as manufacturing processes."],bookRef:"Book p. 124"},{id:"sv-2-754",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The [?] now maintains the standard for design and process FMEAs.`,options:["AIAG","ASQ","IASSC","ISO"],answer:0,hint:"The car industry's own group took over the standard.",steps:[{title:"Key idea",body:"Book p. 124: the **Automotive Industry Action Group (AIAG)** now maintains the design and process FMEA standard."},{title:"Eliminate look-alikes",body:"ASQ, IASSC and ISO are other bodies."}],final:"AIAG → answer **A**",whyWrong:["","Incorrect — ASQ is a quality professional body; it does not maintain the FMEA standard.","Incorrect — IASSC certifies Lean Six Sigma Belts; it does not maintain the FMEA standard.","Incorrect — ISO publishes many standards, but the book names the AIAG for FMEA."],bookRef:"Book p. 124"},{id:"sv-2-755",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:2,stem:`Identify the missing word(s) in the following sentence.

In 1974 the US Navy issued [?], formalising the FMEA method.`,options:["AIAG-VDA handbook","ISO 9001","MIL-STD-1629","QS-9000"],answer:2,hint:"Military standards carry the prefix MIL-STD.",steps:[{title:"Key idea",body:"Book p. 124: the US Navy issued **MIL-STD-1629** in 1974."},{title:"Eliminate look-alikes",body:"The other names are later or unrelated quality standards."}],final:"MIL-STD-1629 → answer **C**",whyWrong:["Incorrect — the AIAG-VDA handbook is a much later automotive FMEA handbook.","Incorrect — ISO 9001 is a quality management system standard, not the 1974 FMEA standard.","","Incorrect — QS-9000 was a later automotive supplier quality requirement."],bookRef:"Book p. 124"},{id:"sv-2-756",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the four types of FMEA described in the book?",options:["Customer FMEA","Design FMEA","Equipment FMEA","System FMEA"],answer:0,hint:"The four: System, Design, Process, Equipment.",steps:[{title:"Key idea",body:"Book p. 124 lists **System, Design, Process and Equipment** FMEAs."},{title:"Apply to the stem",body:"'Customer FMEA' is not on the list; customer impact appears inside every FMEA as the effect."}],final:"Customer FMEA is not a book type → answer **A**",whyWrong:["","Incorrect — the Design FMEA is one of the four types.","Incorrect — the Equipment FMEA is one of the four types.","Incorrect — the System FMEA is one of the four types."],bookRef:"Book p. 124"},{id:"sv-2-757",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:3,stem:"Which is NOT a limitation of the Risk Priority Number?",options:["It multiplies ordinal ratings as if they were measurements","Very different S, O, D combinations can give the same value","A catastrophic severity can be hidden by low O and D scores","It gives the team a ranked order for its actions"],answer:3,hint:"Three are weaknesses; one is the reason RPN is used.",steps:[{title:"Key idea",body:"Weaknesses: ordinal maths, duplicate values, severity swamped, possible gaming."},{title:"Apply to the stem",body:"Ranking failure modes for action is the RPN's purpose, not a limitation."}],final:"Ranking is a benefit → answer **D**",whyWrong:["Incorrect — multiplying ordinal ranks is a real weakness of the RPN.","Incorrect — duplicate values from different combinations are a real weakness.","Incorrect — severity being swamped is a real weakness, hence the severity-first rule.",""],bookRef:"Book p. 135"},{id:"sv-2-758",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:"An engineering team is designing a new **smart-meter enclosure**. Nothing has been built yet, and the team wants to find how the design could fail before it is released. Which type of FMEA should it build?",options:["Design FMEA","Equipment FMEA","Process FMEA","System FMEA"],answer:0,hint:"Before release + product design.",steps:[{title:"Key idea",body:"A DFMEA analyses **product failure modes before release**."},{title:"Apply to the stem",body:"The enclosure is a single product design not yet released → Design FMEA."}],final:"Product design → DFMEA → answer **A**",whyWrong:["","Incorrect — an Equipment FMEA studies the machines that make or test the product.","Incorrect — a Process FMEA studies how a production or service process can fail.","Incorrect — a System FMEA looks at how modules tie together at concept level, not one product's design."],bookRef:"Book p. 124"},{id:"sv-2-759",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:'In a fibre-installation FMEA, the team lists the cause *"heavy rain floods street cabinets"*. In the Class column, how should this cause be labelled?',options:["Controllable (C)","Critical (CTQ)","Noise (N)","Procedural (P)"],answer:2,hint:"Class labels: C, P or N.",steps:[{title:"Key idea",body:"C = controllable, P = procedural (SOP), **N = noise** (cannot or will not be controlled)."},{title:"Apply to the stem",body:"The team cannot control rainfall, so it is a noise input."}],final:"Weather = noise → answer **C**",whyWrong:["Incorrect — controllable inputs are ones the team can set, such as a machine setting.","Incorrect — CTQ is a customer requirement, not an FMEA input class.","","Incorrect — procedural inputs come from methods and SOPs, not the weather."],bookRef:"Book pp. 113, 127"},{id:"sv-2-760",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:3,stem:'For the failure *"wrong speed profile activated"*, the team can fund one action: (1) template-driven provisioning that makes it impossible to select the wrong profile, or (2) an extra quality check after activation. Which choice does Lean thinking prefer?',options:["Option 1, because it prevents the cause and lowers occurrence","Option 2, because it lowers detection, which is weighted most in the RPN","Option 2, because it also lowers the severity rating","Option 1, because it lowers the severity rating to 1"],answer:0,hint:"Prevent beats detect.",steps:[{title:"Key idea",body:"Lean prefers **preventing** the cause (lower O) over finding it earlier (lower D)."},{title:"Eliminate look-alikes",body:"Neither option changes severity; RPN factors carry equal weight."}],final:"Prevention preferred → option 1 → answer **A**",whyWrong:["","Incorrect — S, O and D are weighted equally in the RPN, and a later check still lets the error happen.","Incorrect — a check changes detection, not severity.","Incorrect — preventing the cause lowers occurrence; severity of the effect is unchanged."],bookRef:"Book pp. 135–136"},{id:"sv-2-761",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:"A team finishes its FMEA in Measure. The three highest-RPN causes are *wrong address entry*, *expired stock* and *missed call-backs*. What normally happens to these causes in Analyze?",options:["They are implemented directly as solutions","They become hypotheses to test with data","They are removed from the FMEA because they are known","They are used to set the control limits"],answer:1,hint:"FMEA causes are potential, not proven.",steps:[{title:"Key idea",body:"High-RPN causes are **potential** X's from tribal knowledge."},{title:"Apply to the stem",body:"In Analyze they become hypotheses tested with data before any solution is chosen."}],final:"Test them in Analyze → answer **B**",whyWrong:["Incorrect — FMEA causes are only potential X's; solutions come after they are verified.","","Incorrect — the FMEA keeps them; it is a living document.","Incorrect — control limits come from process data, not FMEA rankings."],bookRef:"Book pp. 123, 238"},{id:"sv-2-762",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:3,stem:"Before a steering meeting, a vendor team lowers several occurrence ratings from 7 to 3. No new data, actions or audits support the change. Which FMEA principle is being ignored?",options:["Severity must be reviewed before occurrence","Detection must always be scored first","Ratings must rest on data and the agreed scales","The RPN must stay below a fixed threshold"],answer:2,hint:"What makes a re-score credible?",steps:[{title:"Key idea",body:"Teams under pressure can nudge O and D down; the defence is **data and consistent, agreed scales**."},{title:"Apply to the stem",body:"Lower occurrence must be earned by fewer failures in the data."}],final:"Ratings need evidence → answer **C**",whyWrong:["Incorrect — no rule orders the ratings; the problem is the missing evidence.","Incorrect — there is no rule to score detection first.","","Incorrect — chasing a threshold is exactly what produced the unsupported scores."],bookRef:"Book pp. 130, 135",trap:"Lowering scores to look good is gaming the FMEA."},{id:"sv-2-763",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:2,stem:"At project closure the Black Belt saves the final FMEA in the project folder and tells the team it is complete. Was this an appropriate action?",options:["Yes, because the FMEA is finished once all actions are taken","Yes, because the FMEA is only a Measure-phase tool","No, because the FMEA should be deleted and rebuilt by the next project","No, because the updated FMEA should go to the process owner as part of the control plan"],answer:3,hint:"Who sustains the process after closure?",steps:[{title:"Key idea",body:"The updated FMEA is part of the **control plan documentation** handed to the process owner."},{title:"Apply to the stem",body:"Filing it as complete stops it being kept up to date."}],final:"Hand it to the process owner → answer **D**",whyWrong:["Incorrect — the FMEA is a living document; it is never finished.","Incorrect — the FMEA also feeds the Control phase monitoring and response plans.","Incorrect — the FMEA is updated, not rebuilt from scratch.",""],bookRef:"Book pp. 125, 570"},{id:"sv-2-764",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:3,stem:'For the failure *"customer billed at the wrong tariff"*, a team member proposes Detection = 1 "because the customer will certainly notice the bill". What is the BEST response?',options:["Reject it: detection rates whether current controls catch the failure before it reaches the customer","Accept it: the customer noticing the failure counts as almost certain detection","Accept it, but raise severity to balance the low detection score","Reject it: detection must always be scored 10 for billing failures"],answer:0,hint:"Who should catch the failure?",steps:[{title:"Key idea",body:"Detection = the chance the **current control** catches the failure before it moves on (book p. 134)."},{title:"Apply to the stem",body:"If the customer is the first to see it, the controls did not detect it, so DET should be high."}],final:"Customer finding it ≠ detection → answer **A**",whyWrong:["","Incorrect — a customer finding the error means the controls failed; that is poor detection.","Incorrect — severity rates the effect; it is not used to balance another rating.","Incorrect — detection depends on the strength of the controls, not on the process type."],bookRef:"Book pp. 133–134"},{id:"sv-2-765",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:3,stem:"An operator copies its proven number-porting process to a new country with different IT systems. The team reuses the original PFMEA unchanged. Was this an appropriate action?",options:["Yes, because the process steps are the same","No, because a PFMEA must be updated when a carry-over process is used in a new setting","Yes, because the PFMEA is only updated after a failure","No, because a new Design FMEA must replace the PFMEA"],answer:1,hint:"Carry-over designs are a named update trigger.",steps:[{title:"Key idea",body:"Book p. 125: update the FMEA when carry-over designs or processes are **used in new settings**."},{title:"Apply to the stem",body:"New systems and a new country can create new failure modes and ratings."}],final:"Update for the new setting → answer **B**",whyWrong:["Incorrect — the same steps in a new environment can fail in new ways.","","Incorrect — the FMEA is a prevention tool; waiting for failures defeats it.","Incorrect — the process, not a product design, is being reused; the PFMEA is updated."],bookRef:"Book p. 125"},{id:"sv-2-766",phase:2,topic:"2.1.4",qtype:"output",difficulty:3,stem:`An FMEA action-results extract:

\`\`\`
Failure mode            Action taken                    S  O  D  ->  S  O  D
Wrong tariff applied    Validation rule at order entry  8  6  5  ->  8  2  5
Port request lost       Daily reconciliation report     7  5  8  ->  7  5  3
SIM sent to old address Address check against postcode  6  4  6  ->  6  2  4
Router shipped faulty   Extra final inspection          9  3  7  ->  5  3  2
\`\`\`

Which re-score should the Black Belt challenge?`,options:["Wrong tariff applied, because a validation rule cannot lower occurrence","Port request lost, because a report cannot lower detection","Router shipped faulty, because inspection cannot lower severity","SIM sent to old address, because both O and D changed"],answer:2,hint:"Which factor can each kind of action move?",steps:[{title:"Key idea",body:"Prevention lowers O, controls lower D, and **severity changes only with a design change**."},{title:"Apply to the stem",body:"The router row drops S from 9 to 5 after an inspection step, which is not credible."}],final:"Challenge the router severity drop → answer **C**",whyWrong:["Incorrect — a rule that blocks the wrong tariff at entry prevents the cause, so lower O is credible.","Incorrect — a reconciliation report finds lost requests, so lower D is credible.","","Incorrect — one action can both prevent some causes and catch others; nothing wrong is shown."],bookRef:"Book p. 135"},{id:"sv-2-767",phase:2,topic:"2.1.4",qtype:"output",difficulty:2,stem:`A team uses this **transactional** severity scale:

\`\`\`
Rating  Effect
10      May endanger the company's ability to do business
 7      Customer complaint; regulator may be informed
 4      Internal rework; customer not affected
 1      No noticeable effect
\`\`\`

A failure causes internal rework but the customer never sees it. Which severity applies?`,options:["1","4","7","10"],answer:1,hint:"Match the effect description, not the cause.",steps:[{title:"Key idea",body:"Severity is read from the **effect** column of the agreed scale."},{title:"Apply to the stem",body:"'Internal rework; customer not affected' is rating 4."}],final:"Internal rework → 4 → answer **B**",whyWrong:["Incorrect — 1 means no noticeable effect, but rework is an effect.","","Incorrect — 7 needs a customer complaint, which does not happen here.","Incorrect — 10 is reserved for failures that may endanger the business."],bookRef:"Book p. 130"},{id:"sv-2-768",phase:2,topic:"2.1.4",qtype:"output",difficulty:3,stem:`An FMEA extract for one failure mode:

\`\`\`
Failure mode: Order activated late
Effect: SLA breach credit paid
Cause                          S  O  D  RPN
Missing customer documents     6  7  4  168
System queue backlog           6  4  6  144
Wrong team assigned            6  3  3   54
\`\`\`

Which statement about this extract is CORRECT?`,options:["Severity should differ by cause, so the extract is wrong","Only the cause with the highest RPN should appear in the FMEA","The three causes should be combined into one row with one RPN","Severity is the same on every row because the three causes share one effect"],answer:3,hint:"One failure mode → one effect → one severity, many causes.",steps:[{title:"Key idea",body:"A failure mode can have **several causes**, each on its own row with its own O, D and RPN."},{title:"Apply to the stem",body:"The effect is shared, so S = 6 on every row is correct."}],final:"Same effect → same severity → answer **D**",whyWrong:["Incorrect — severity rates the effect, which is the same for all three causes.","Incorrect — every potential cause is listed so each can be ranked.","Incorrect — each cause needs its own occurrence, detection and RPN.",""],bookRef:"Book pp. 128–132"},{id:"sv-2-769",phase:2,topic:"2.1.4",qtype:"sequence",difficulty:1,stem:`Put these FMEA steps for one failure mode in order.

- **P** Take the action and record the date it took effect
- **Q** Calculate the RPN from S, O and D
- **R** Re-score S, O, D and the new RPN
- **S** Record a recommended action with an owner and target date`,options:["Q → S → P → R","S → Q → P → R","Q → P → S → R","Q → S → R → P"],answer:0,hint:"Rank → plan → do → re-score.",steps:[{title:"Key idea",body:"Template order: RPN → recommended actions, owner and date → actions taken → new S, O, D and RPN."},{title:"Apply to the stem",body:"So Q, S, P, R."}],final:"Q → S → P → R → answer **A**",whyWrong:["","Incorrect — the action is chosen after the RPN shows where the risk is.","Incorrect — the action must be recorded and assigned before it is taken.","Incorrect — re-scoring comes after the action is taken, not before."],bookRef:"Book p. 135"},{id:"sv-2-770",phase:2,topic:"2.1.4",qtype:"sequence",difficulty:2,stem:"In which order are these Measure-phase tools normally created?",options:["Fishbone → process map → FMEA → X-Y matrix","Process map → fishbone → X-Y matrix → FMEA","Process map → X-Y matrix → fishbone → FMEA","FMEA → fishbone → process map → X-Y matrix"],answer:1,hint:"Each tool feeds the next.",steps:[{title:"Key idea",body:"The book's order: **process map → fishbone → X-Y matrix → FMEA**."},{title:"Apply to the stem",body:"Steps from the map, causes from the fishbone, ranking in the X-Y matrix, then risk in the FMEA."}],final:"Map → fishbone → X-Y → FMEA → answer **B**",whyWrong:["Incorrect — the process map comes first, and the X-Y matrix comes before the FMEA.","","Incorrect — the X-Y matrix rates causes that the fishbone has already listed.","Incorrect — the FMEA needs the steps and causes the earlier tools supply."],bookRef:"Book pp. 118–123"},{id:"sv-2-771",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"What does the abbreviation **FMEA** stand for?",options:["Failure Measurement and Error Assessment","Fault Modes and Error Analysis","Failure Modes and Effects Analysis","Failure Monitoring and Effects Audit"],answer:2,hint:"Modes = ways to fail; effects = what they cause.",steps:[{title:"Key idea",body:"FMEA = **Failure Modes and Effects Analysis**: how a step can fail (modes) and what that does (effects)."},{title:"Eliminate look-alikes",body:"The other expansions swap in look-alike words."}],final:"Failure Modes and Effects Analysis → answer **C**",whyWrong:["Incorrect — the M stands for modes (ways of failing), not measurement.","Incorrect — the method studies failures and their effects, not faults and errors.","","Incorrect — the A stands for analysis; FMEA is not an audit of monitoring."],bookRef:"Book p. 123"},{id:"sv-2-772",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:"What can an FMEA rank that a Pareto chart of last year's defects cannot?",options:["Defect categories in descending order of frequency","The vital few categories that cause most of the defects","The cumulative percentage of defects by category","Potential failures that have not yet happened, scored for severity, occurrence and detection"],answer:3,hint:"Pareto looks back; FMEA looks ahead.",steps:[{title:"Key idea",body:"A Pareto chart ranks defects that **have already occurred**. An FMEA **predicts** failures and rates their risk."},{title:"Apply to the stem",body:"Only the FMEA can rank a failure that has never yet happened."}],final:"FMEA ranks potential failures → answer **D**",whyWrong:["Incorrect — ranking categories by frequency is exactly what a Pareto chart does.","Incorrect — finding the vital few from historical counts is the Pareto principle.","Incorrect — the cumulative percentage line is part of a Pareto chart.",""],bookRef:"Book pp. 123, 125"},{id:"sv-2-773",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"In the Black Belt roadmap, in which DMAIC phase is the FMEA first built?",options:["Analyze","Control","Define","Measure"],answer:3,hint:"It sits with the process map, fishbone and X-Y matrix.",steps:[{title:"Key idea",body:"The FMEA is a Measure tool (syllabus 2.1.4), built after the process map, fishbone and X-Y matrix."},{title:"Apply to the stem",body:"Later phases test, improve and monitor what it ranks."}],final:"Measure → answer **D**",whyWrong:["Incorrect — Analyze tests the causes the FMEA has ranked; it does not first build it.","Incorrect — Control uses and updates the FMEA; it already exists by then.","Incorrect — Define sets the charter and scope; the process tools come next.",""],bookRef:"Book p. 123; Syllabus 2.1.4"},{id:"sv-2-774",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"In Improve, why should the team update the FMEA for its proposed new process before full roll-out?",options:["The change can create new failure modes that need rating and controls","The FMEA must be rebuilt from scratch in every phase","Updating the FMEA proves the solution removes the root cause","Severity ratings must be lowered once a solution is chosen"],answer:0,hint:"A process change is an update trigger.",steps:[{title:"Key idea",body:"Book p. 125: the FMEA is updated whenever the process **changes**."},{title:"Apply to the stem",body:"A new process design can fail in new ways, so its risks are rated before roll-out."}],final:"New process → new failure modes → answer **A**",whyWrong:["","Incorrect — the FMEA is updated, not rebuilt; it is a living document.","Incorrect — proof comes from data such as a pilot, not from FMEA scores.","Incorrect — severity changes only if the effect itself becomes less serious."],bookRef:"Book p. 125"},{id:"sv-2-775",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"According to the book, which industry adopted FMEA in the late 1970s?",options:["Automotive","Banking","Healthcare","Telecommunications"],answer:0,hint:"The AIAG is part of this industry.",steps:[{title:"Key idea",body:"Book p. 124: after Apollo and MIL-STD-1629, the **car industry** adopted FMEA in the late 1970s."},{title:"Apply to the stem",body:"That is why the Automotive Industry Action Group maintains the standard."}],final:"Automotive → answer **A**",whyWrong:["","Incorrect — the book does not name banking in FMEA's history.","Incorrect — the book does not name healthcare in FMEA's history.","Incorrect — telecoms use FMEA today, but the book names the car industry."],bookRef:"Book p. 124"},{id:"sv-2-776",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"How does an FMEA differ from an X-Y matrix?",options:["The FMEA rates X's against several Y's; the X-Y matrix rates failure risks","The FMEA rates failure risks by severity, occurrence and detection; the X-Y matrix rates X's against several Y's","The FMEA uses real process data; the X-Y matrix is pure brainstorming","The FMEA is only for design; the X-Y matrix is only for processes"],answer:1,hint:"What does each tool score?",steps:[{title:"Key idea",body:"The X-Y matrix rates each X's impact on several weighted Y's. The FMEA rates each failure's **S, O and D** to give an RPN."},{title:"Eliminate look-alikes",body:"The reversed option and the 'real data' claim are look-alike traps."}],final:"FMEA = risk; X-Y = impact on Y's → answer **B**",whyWrong:["Incorrect — the roles are reversed.","","Incorrect — both start from team knowledge; the FMEA is not defined by real data.","Incorrect — FMEAs exist for processes too, and the X-Y matrix is not limited to processes."],bookRef:"Book pp. 118–123"},{id:"sv-2-777",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:"Which statement about the RPN and severity is CORRECT?",options:["A failure mode with severity 10 always has the highest RPN","Severity is left out of the RPN because it rarely changes","A failure mode with severity 10 can have a lower RPN than a minor failure mode","A high RPN always means the effect is hazardous"],answer:2,hint:"The RPN multiplies three factors.",steps:[{title:"Key idea",body:"RPN = S × O × D, so a low O and D can bury a catastrophic S."},{title:"Apply to the stem",body:"That is why very high severities are reviewed on their own."}],final:"Severity can be swamped in the RPN → answer **C**",whyWrong:["Incorrect — low occurrence and good detection can pull a severity-10 RPN down.","Incorrect — severity is one of the three factors in the RPN.","","Incorrect — a high RPN can come from frequent, poorly detected minor failures."],bookRef:"Book p. 135"},{id:"sv-2-778",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"Which statement about FMEA rating scales is CORRECT?",options:["Only the AIAG wording may be used for any FMEA","Each failure mode may be scored on a different scale","Transactional processes cannot be given a severity scale","A team may define its own scale, provided it uses it consistently"],answer:3,hint:"Consistency over wording.",steps:[{title:"Key idea",body:"Book p. 130: you may define your own scale; **consistency matters more** than the exact words."},{title:"Eliminate look-alikes",body:"AIAG-only, mixed scales and 'no transactional scale' all contradict the book."}],final:"Own scale, used consistently → answer **D**",whyWrong:["Incorrect — the book allows a team's own scale; consistency matters more than exact words.","Incorrect — mixing scales makes the RPN ranking meaningless.","Incorrect — the book gives a transactional severity scale.",""],bookRef:"Book p. 130"},{id:"sv-2-779",phase:2,topic:"2.1.4",qtype:"statements",difficulty:3,stem:`Which statements about the limitations of the RPN are CORRECT?

1. An RPN of 200 is twice as risky as an RPN of 100.
2. RPN action thresholds are fixed by the AIAG standard.
3. Severity, occurrence and detection are ordinal rankings.
4. Different combinations of ratings can give the same RPN.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Ranks, not measurements.",steps:[{title:"Key idea",body:"S, O and D are ordinal, so the RPN only ranks; many S, O, D combinations collide on one value."},{title:"Apply to the stem",body:"Statements 3 and 4 are true; 1 and 2 are common myths."}],final:"3 and 4 → answer **C**",whyWrong:["Incorrect — both are false: ranks give no true ratio, and thresholds are local conventions.","Incorrect — statement 3 is true, but no standard fixes a universal RPN threshold.","","Incorrect — statement 4 is true, but ordinal scores do not support 'twice as risky'."],bookRef:"Book p. 135"},{id:"sv-2-780",phase:2,topic:"2.1.4",qtype:"statements",difficulty:2,stem:`Which statements about the current process controls column are CORRECT?

1. It records the improvements the team plans to make.
2. It records the controls already in place today.
3. A strong control leads to a low detection rating.
4. Controls are scored on the severity scale.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Current = today.",steps:[{title:"Key idea",body:"Current controls are the SPC, poka-yoke or inspection in place **now**; their strength sets DET (1 = almost certain)."},{title:"Apply to the stem",body:"Statements 2 and 3 are true."}],final:"2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: planned improvements go in the recommended actions column.","","Incorrect — statement 3 is true, but controls are judged with the detection scale, not severity.","Incorrect — both are false: planned actions and severity scoring belong elsewhere."],bookRef:"Book pp. 133–134"},{id:"sv-2-781",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The FMEA is a [?] document: it is updated whenever the process or design changes.`,options:["controlled","living","signed-off","static"],answer:1,hint:"It is never finished.",steps:[{title:"Key idea",body:"The book calls the FMEA a **living document** because it is updated as designs and processes change."},{title:"Apply to the stem",body:"It keeps evolving through the project and after it."}],final:"living → answer **B**",whyWrong:["Incorrect — document control is about versions, not why the FMEA keeps changing.","","Incorrect — sign-off suggests a finished document; the FMEA is never finished.","Incorrect — static is the opposite of how the book describes the FMEA."],bookRef:"Book p. 125"},{id:"sv-2-782",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

In the FMEA Class column, an input governed by a standard operating procedure is labelled [?].`,options:["controllable","critical","noise","procedural"],answer:3,hint:"C, P or N.",steps:[{title:"Key idea",body:"Class labels: C = controllable, **P = procedural** (SOPs, standard activities), N = noise."},{title:"Apply to the stem",body:"An SOP-governed input is procedural."}],final:"procedural → answer **D**",whyWrong:["Incorrect — controllable inputs are settings the team can adjust, such as a temperature.","Incorrect — 'critical' describes a proven critical X, not a Class label.","Incorrect — noise inputs are ones the team cannot or will not control.",""],bookRef:"Book pp. 113, 127"},{id:"sv-2-783",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:2,stem:"Which is NOT a suitable recommended action for a high-RPN failure mode?",options:["Lowering the severity score without changing the design","Mistake-proofing the step so the cause cannot occur","Putting SPC on the key input that drives the cause","Strengthening the check before the order is dispatched"],answer:0,hint:"Actions change the process, not just the numbers.",steps:[{title:"Key idea",body:"Actions attack the **cause** (lower O) or the **control** (lower D). Severity changes only with a design change."},{title:"Apply to the stem",body:"Re-writing a severity score with no design change is not an action at all."}],final:"Changing S on paper is not an action → answer **A**",whyWrong:["","Incorrect — mistake-proofing is a genuine action that lowers occurrence.","Incorrect — SPC on a key input is a genuine action that helps prevent or detect the cause.","Incorrect — a stronger check is a genuine action that lowers detection."],bookRef:"Book pp. 135–136"},{id:"sv-2-784",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:2,stem:"Which is NOT a use of the FMEA in the Control phase?",options:["Choosing the highest-risk X's to monitor","Proving which X is the root cause","Giving the response plan its triggers and owners","Handing re-scored risks to the process owner"],answer:1,hint:"Root-cause proof happened earlier.",steps:[{title:"Key idea",body:"In Control the FMEA feeds the monitoring and response plan and is handed to the process owner."},{title:"Apply to the stem",body:"Proving root causes is done with data in Analyze, not in Control."}],final:"Root-cause proof is not a Control use → answer **B**",whyWrong:["Incorrect — the highest-risk X's are the ones to monitor in Control.","","Incorrect — each failure mode needs a trigger, response and owner in the response plan.","Incorrect — the updated FMEA is part of the control plan handed to the process owner."],bookRef:"Book p. 570"},{id:"sv-2-785",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:"In Control, the process owner sees a new failure: port requests timing out after a system upgrade. This failure mode is not in the project's FMEA. What should happen?",options:["Ignore it, because the FMEA was completed in Measure","Start a new FMEA and discard the old one","Add it to the FMEA, rate it and update the monitoring and response plans","Record it only in the project's lessons learned"],answer:2,hint:"Living document + Control use.",steps:[{title:"Key idea",body:"The FMEA is updated when the process changes, and it feeds the monitoring and response plans."},{title:"Apply to the stem",body:"The new failure mode is added, scored and linked to a trigger, response and owner."}],final:"Add, rate, update plans → answer **C**",whyWrong:["Incorrect — the FMEA is a living document; it is not frozen after Measure.","Incorrect — the existing FMEA is updated, not thrown away.","","Incorrect — lessons learned do not rate or control the new risk."],bookRef:"Book pp. 125, 570"},{id:"sv-2-786",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:3,stem:'After a network redesign adds automatic failover, a single link failure no longer causes a customer outage. The team proposes lowering the severity of *"link failure"*. Was this an appropriate action?',options:["Yes, because severity should fall after any improvement","No, because severity can never change once it is scored","No, because only occurrence and detection may ever be re-scored","Yes, because the design change makes the effect itself less serious"],answer:3,hint:"What is the one route to a lower severity?",steps:[{title:"Key idea",body:"Severity is a property of the **effect**; it changes only if the design changes so the effect becomes less serious."},{title:"Apply to the stem",body:"Failover means the customer no longer loses service, so a lower severity is justified."}],final:"Design change → lower severity is valid → answer **D**",whyWrong:["Incorrect — most improvements lower O or D; severity falls only when the effect becomes less serious.","Incorrect — severity can change when the design changes the effect.","Incorrect — severity may be re-scored after a genuine design change.",""],bookRef:"Book pp. 135–136"},{id:"sv-2-787",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:2,stem:"To save time, a team decides to rate severity on a 1–5 scale but occurrence and detection on 1–10 scales. Was this an appropriate action?",options:["No, because all three ratings use a 1–10 scale so the RPN ranks consistently","Yes, because severity changes less often than the other ratings","Yes, because any scale is acceptable for any rating","No, because severity must be scored on a 1–100 scale"],answer:0,hint:"S, O and D share one range.",steps:[{title:"Key idea",body:"Book: all three ratings use a **1–10 scale**, applied consistently; the RPN then runs from 1 to 1,000."},{title:"Apply to the stem",body:"A 1–5 severity scale shrinks severity's weight and distorts the ranking."}],final:"All three on 1–10 → answer **A**",whyWrong:["","Incorrect — how often a rating changes does not justify a different scale.","Incorrect — the team may word its own scale, but all three use 1–10 and are applied consistently.","Incorrect — no FMEA rating uses a 1–100 scale."],bookRef:"Book pp. 129–134"},{id:"sv-2-788",phase:2,topic:"2.1.4",qtype:"output",difficulty:1,stem:`An FMEA after the first round of actions:

\`\`\`
Failure mode               Old RPN   New RPN
No-access appointment        280        60
Splice loss high             224        48
Wrong profile activated      180        63
Drill hazard                 120        20
\`\`\`

Which failure mode heads the ranking for the next round of improvement?`,options:["No-access appointment","Wrong profile activated","Splice loss high","Drill hazard"],answer:1,hint:"Rank on the re-scored column.",steps:[{title:"Key idea",body:"After re-scoring, the **new** ranking guides the next round; the FMEA is never finished."},{title:"Apply to the stem",body:"The highest new RPN is 63, for wrong profile activated."}],final:"Highest new RPN = 63 → answer **B**",whyWrong:["Incorrect — it had the highest old RPN, but its new RPN of 60 is now second.","","Incorrect — its new RPN of 48 is third.","Incorrect — its new RPN of 20 is the lowest."],bookRef:"Book p. 135"},{id:"sv-2-789",phase:2,topic:"2.1.4",qtype:"output",difficulty:2,stem:`FMEA ratings before and after an action:

\`\`\`
Failure mode: Port request rejected
            S   O   D
Before      7   6   8
After       7   6   3
Action: automated check flags rejected requests within 1 hour
\`\`\`

Which conclusion is CORRECT?`,options:["Rejections now occur much less often","The effect of a rejection is now less serious","Rejections still occur as often, but are now caught much earlier","The cause of rejections has been removed"],answer:2,hint:"Which factor moved?",steps:[{title:"Key idea",body:"Only **detection** changed (8 → 3): the failure is found sooner, not prevented."},{title:"Eliminate look-alikes",body:"O and S are unchanged, so frequency and seriousness are the same."}],final:"Detection-only improvement → answer **C**",whyWrong:["Incorrect — occurrence is unchanged at 6.","Incorrect — severity is unchanged at 7.","","Incorrect — removing the cause would lower occurrence, which did not change."],bookRef:"Book pp. 135–136"},{id:"sv-2-790",phase:2,topic:"2.1.4",qtype:"output",difficulty:2,stem:`An FMEA register for an operator:

\`\`\`
FMEA   Subject                                   Type recorded
F-01   Home router before market release           Design
F-02   Order-to-activation process                 Process
F-03   Optical test set used by field technicians  Process
F-04   Billing-system concept (modules linking)    System
\`\`\`

Which entry has the wrong FMEA type?`,options:["F-01","F-02","F-04","F-03"],answer:3,hint:"What does each type study?",steps:[{title:"Key idea",body:"System = concept, Design = product before release, Process = process, **Equipment = machines that make or test**."},{title:"Apply to the stem",body:"A test set is equipment, so F-03 should be an Equipment FMEA."}],final:"Test set → Equipment, not Process → answer **D**",whyWrong:["Incorrect — a product before release is correctly a Design FMEA.","Incorrect — a running order process is correctly a Process FMEA.","Incorrect — a concept where modules link is correctly a System FMEA.",""],bookRef:"Book p. 124"},{id:"sv-2-791",phase:2,topic:"2.1.4",qtype:"true-false",difficulty:1,stem:"A Design FMEA is completed after the product has been released to customers. True or False?",options:["True","False"],answer:1,hint:"Design = before release.",steps:[{title:"Key idea",body:"Book p. 124: the DFMEA analyses product failure modes **before release**."},{title:"Apply to the stem",body:"So the statement is false."}],final:"False → answer **False**",whyWrong:["Incorrect — a Design FMEA analyses product failure modes before release.",""],bookRef:"Book p. 124"},{id:"sv-2-792",phase:2,topic:"2.1.4",qtype:"sequence",difficulty:2,stem:`A process step is changed. Put these FMEA update steps in order.

- **P** Rate severity, occurrence and detection for the new failure modes
- **Q** Identify which steps of the process map have changed
- **R** Rank by RPN and assign actions with owners and dates
- **S** List the new ways the changed steps could fail`,options:["Q → S → P → R","S → Q → P → R","Q → P → S → R","Q → S → R → P"],answer:0,hint:"Step → mode → rate → act.",steps:[{title:"Key idea",body:"The FMEA reads left to right: step → failure mode → ratings → RPN → actions."},{title:"Apply to the stem",body:"So Q, S, P, R."}],final:"Q → S → P → R → answer **A**",whyWrong:["","Incorrect — the changed steps must be found before their failure modes can be listed.","Incorrect — failure modes must exist before they can be rated.","Incorrect — actions are assigned after rating and ranking."],bookRef:"Book pp. 125–135"},{id:"sv-2-793",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"In basic statistics, what is a **population**?",options:["The list from which a sample is drawn","All the items that have the property of interest","A smaller subset used to make an inference","A value calculated from sample data"],answer:1,hint:"Population, frame, sample: whole, list, subset.",steps:[{title:"Key idea",body:'Book p. 141: the **population** is all the items that have the property of interest, e.g. "all trades completed in 2001".'},{title:"Eliminate look-alikes",body:"Frame = the list; sample = the subset; statistic = a value from the sample."}],final:"Population = all items of interest → answer **B**",whyWrong:["Incorrect — the list a sample is drawn from is the frame.","","Incorrect — a smaller subset used for inference is a sample.","Incorrect — a value calculated from sample data is a statistic."],bookRef:"Book p. 141"},{id:"sv-2-794",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"What is a **sample** used for in basic statistics?",options:["To list every item in the population","To replace the need to define the population","To make an inference about the population","To describe only the items not measured"],answer:2,hint:"A sample is small, but its job is big.",steps:[{title:"Key idea",body:"Book p. 141: a sample is a much smaller subset of the population used to make an **inference**."},{title:"Apply to the stem",body:"The sample stands in for the population at much lower cost."}],final:"Sample → inference about population → answer **C**",whyWrong:["Incorrect — listing every item describes the population or the frame, not a sample.","Incorrect — the population must still be defined carefully before sampling.","","Incorrect — a sample describes the items that were measured and is used to infer about the rest."],bookRef:"Book p. 141"},{id:"sv-2-795",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which describes a **parameter**?",options:["A value that describes a sample, written with a Latin letter such as x̄","The list of items from which a sample is drawn","The number of items chosen for a sample","A value that describes a population, written with a Greek letter such as μ"],answer:3,hint:"Parameter ↔ Population; Statistic ↔ Sample.",steps:[{title:"Key idea",body:"Parameters describe **populations** (μ, σ, σ², P, N); statistics describe **samples** (x̄, s, s², p, n)."},{title:"Apply to the stem",body:"So a parameter is a population value with a Greek symbol."}],final:"Parameter = population value → answer **D**",whyWrong:["Incorrect — a value describing a sample is a statistic.","Incorrect — the list is the frame.","Incorrect — the number of sampled items is the sample size n, a statistic-side symbol.",""],bookRef:"Book pp. 140–141",trap:"P-for-Population, S-for-Sample."},{id:"sv-2-796",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which pair correctly matches a population parameter with the sample statistic that estimates it?",options:["μ (parameter) and x̄ (statistic)","x̄ (parameter) and μ (statistic)","s (parameter) and σ (statistic)","n (parameter) and N (statistic)"],answer:0,hint:"Greek letters and capital N belong to the population.",steps:[{title:"Key idea",body:"Population: μ, σ, σ², P, N. Sample: x̄, s, s², p, n."},{title:"Apply to the stem",body:"The sample mean x̄ estimates the population mean μ; the other pairs are swapped."}],final:"μ ↔ x̄ → answer **A**",whyWrong:["","Incorrect — the roles are reversed: x̄ is the sample mean and μ the population mean.","Incorrect — reversed: σ is the population standard deviation and s the sample one.","Incorrect — reversed: N is the population size and n the sample size."],bookRef:"Book p. 141"},{id:"sv-2-797",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Why does the book say we work with **sample** formulas most of the time?",options:["Because sample formulas are always more accurate","Because we usually have a sample, not the whole population","Because population formulas apply only to attribute data","Because sample formulas do not need a frame"],answer:1,hint:"What data do Green Belts normally hold?",steps:[{title:"Key idea",body:"Measuring every item is rarely practical, so most project data are **samples**."},{title:"Apply to the stem",body:"Hence the book says most of the time we use the sample formulas."}],final:"We usually hold samples → answer **B**",whyWrong:["Incorrect — sample results are estimates; they are not more accurate than true population values.","","Incorrect — population formulas apply to any data type when every item is measured.","Incorrect — a sample is still drawn from a frame."],bookRef:"Book p. 141"},{id:"sv-2-798",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"In the book's terms, what is **attribute** data?",options:["Whole-number counts such as the number of defects","Measurements on a scale where decimals are meaningful","Data that can take only two values, such as pass or fail","Ordered ratings such as poor, good and excellent"],answer:2,hint:"The book separates binary attribute data from counts.",steps:[{title:"Key idea",body:"Book p. 142: **attribute** data are binary (Yes/No, Go/No-go, Pass/Fail); discrete data are counts; continuous data are measured."},{title:"Apply to the stem",body:"Only the two-value option fits the attribute definition."}],final:"Attribute = two values → answer **C**",whyWrong:["Incorrect — whole-number counts are discrete (count) data.","Incorrect — measurements with meaningful decimals are continuous data.","","Incorrect — ordered ratings describe the ordinal scale of measurement."],bookRef:"Book pp. 142–143"},{id:"sv-2-799",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"What quick test does the book give for telling continuous data from discrete data?",options:["Whether the value is stored as a number","Whether the value is above or below the target","Whether the value came from a sample","Whether the value can be meaningfully subdivided"],answer:3,hint:'Think of "2.543 inches" versus "2.543 defects".',steps:[{title:"Key idea",body:"If a value can be split meaningfully (2.543 inches), it is continuous; if not (2.543 defects), it is discrete."},{title:"Apply to the stem",body:"Being numeric, near target or sampled does not decide the type."}],final:"Meaningful subdivision test → answer **D**",whyWrong:["Incorrect — counts and codes are also stored as numbers, yet they are not continuous.","Incorrect — position relative to a target says nothing about the data type.","Incorrect — samples and populations can both hold continuous or discrete data.",""],bookRef:"Book p. 143"},{id:"sv-2-800",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which data type does the book call **the lowest level of data**?",options:["Attribute","Continuous","Discrete","Ratio"],answer:0,hint:"Two values hold the least information.",steps:[{title:"Key idea",body:"The book calls binary **attribute** data the lowest level of data."},{title:"Apply to the stem",body:"A yes/no tells nothing about how far a unit is from target."}],final:"Attribute = lowest level → answer **A**",whyWrong:["","Incorrect — continuous data carry the most information.","Incorrect — discrete counts carry more information than a simple yes/no.","Incorrect — ratio is a scale of measurement, and the most informative one."],bookRef:"Book p. 142"},{id:"sv-2-801",phase:2,topic:"2.2.1",qtype:"concept",difficulty:3,stem:"A team reports the **percentage of defective invoices** each week. What kind of data is this percentage built from?",options:["Counts of defective and good invoices, so discrete data","Measured amounts, so continuous data","Ordered ratings, so ordinal data","Labels with no order, so nominal data"],answer:0,hint:"Look at what was actually recorded for each invoice.",steps:[{title:"Key idea",body:"Each invoice is classified defective or good, and the defectives are **counted**."},{title:"Apply to the stem",body:"A percentage made from counts is still based on discrete data, even with decimals."}],final:"% defective comes from counts → answer **A**",whyWrong:["","Incorrect — a percentage can show decimals, but it is built from counts, not measurements.","Incorrect — defective/good is a classification, not an ordered rating.","Incorrect — the percentage is a summary of counts, not a label."],bookRef:"Book pp. 142–143",trap:"Decimals in a percentage do not make it continuous."},{id:"sv-2-802",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"What can you do with data on a **nominal** scale?",options:["Put the values in a meaningful order","Only say whether two values are the same or different","Say how far apart two values are","Say one value is twice another"],answer:1,hint:"Nominal = names only.",steps:[{title:"Key idea",body:"Nominal data are names or labels (blood type, country of birth) with no order."},{title:"Apply to the stem",body:"The only comparison allowed is same or different."}],final:"Nominal = same or different → answer **B**",whyWrong:["Incorrect — ordering is the extra power of the ordinal scale.","","Incorrect — meaningful differences come with the interval scale.","Incorrect — ratios need a true zero, which only the ratio scale has."],bookRef:"Book p. 144"},{id:"sv-2-803",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"What distinguishes an **ordinal** scale from an **interval** scale?",options:["Ordinal values have a true zero, but interval values do not","Ordinal values cannot be ordered, but interval values can","Ordinal values are ordered, but the differences between them have no exact meaning","Ordinal values allow ratios, but interval values only allow differences"],answer:2,hint:"NOIR adds one power at each step.",steps:[{title:"Key idea",body:"Ordinal: order only (car size, poor/good/excellent). Interval: order **and** meaningful differences, but no true zero."},{title:"Eliminate look-alikes",body:"True zero and ratios belong to the ratio scale."}],final:"Ordinal = order without exact gaps → answer **C**",whyWrong:["Incorrect — neither scale has a true zero; that belongs to the ratio scale.","Incorrect — ordinal values can be ordered; that is what 'ordinal' means.","","Incorrect — ratios need the ratio scale; ordinal allows no arithmetic at all."],bookRef:"Book pp. 144–145"},{id:"sv-2-804",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which feature makes a scale of measurement a **ratio** scale?",options:["Values that are labels with no order","An order without equal differences","Equal differences but an arbitrary zero","A true zero that means none of the characteristic"],answer:3,hint:"Only one scale lets you say 'twice as much'.",steps:[{title:"Key idea",body:"Ratio data have a **true zero** (0 g of fat = no fat), so all arithmetic, including division, is meaningful."},{title:"Eliminate look-alikes",body:"The other options define nominal, ordinal and interval."}],final:"True zero → ratio → answer **D**",whyWrong:["Incorrect — labels with no order describe the nominal scale.","Incorrect — order without equal differences is the ordinal scale.","Incorrect — equal differences with an arbitrary zero is the interval scale.",""],bookRef:"Book p. 145"},{id:"sv-2-805",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:'Why is an IQ score of 120 not "1.2 times" an IQ score of 100?',options:["IQ is on an interval scale with no true zero","IQ is on a nominal scale with no order","IQ is on an ordinal scale with no meaningful order","IQ is on a ratio scale with an arbitrary zero"],answer:0,hint:"Ratios need a true zero.",steps:[{title:"Key idea",body:"The book's interval example is IQ: differences are meaningful, but there is **no true zero**."},{title:"Apply to the stem",body:"Without a true zero, '1.2 times' has no meaning."}],final:"Interval → no ratios → answer **A**",whyWrong:["","Incorrect — IQ scores are ordered and differences are meaningful, so not nominal.","Incorrect — ordinal data are ordered by definition; and IQ differences are meaningful.","Incorrect — a ratio scale has a true zero, not an arbitrary one."],bookRef:"Book p. 145"},{id:"sv-2-806",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which is a reason the book gives for preferring continuous data?",options:["It never needs a sampling frame","It shows how far each unit is from the target","It removes the need for a measurement system analysis","It can always be turned into ratio-scale counts"],answer:1,hint:'"Continuous data is always more desirable."',steps:[{title:"Key idea",body:"Continuous data show **how far** each unit is from target, need smaller samples and allow more powerful tools (book p. 146)."},{title:"Eliminate look-alikes",body:"Frames and MSA are still needed; counts are the less informative type."}],final:"Continuous shows distance from target → answer **B**",whyWrong:["Incorrect — continuous data are still sampled from a frame.","","Incorrect — every measurement system, continuous or not, must be checked by MSA.","Incorrect — counts are discrete; continuous data are not turned into counts."],bookRef:"Book p. 146"},{id:"sv-2-807",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"According to the book, what should decisions in a Six Sigma project be based on?",options:["Consensus","Data","Experience","Opinion"],answer:1,hint:'"I think", "I feel", "in my opinion".',steps:[{title:"Key idea",body:'Book p. 142: the goal is to decide based on **data**, not on "I think", "I feel" or "in my opinion".'},{title:"Apply to the stem",body:"Statistics turns data into the evidence for decisions."}],final:"Decide on data → answer **B**",whyWrong:["Incorrect — agreement does not replace evidence.","","Incorrect — experience helps form ideas, but decisions rest on data.","Incorrect — 'I think' and 'in my opinion' are what the book wants to replace."],bookRef:"Book p. 142"},{id:"sv-2-808",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which statement about a sampling frame is CORRECT?",options:["A frame is always identical to the population","A frame is the subset of items that were measured","A list of licensed drivers may represent the adult public better than a list of registered voters","A frame is needed only when the population is small"],answer:2,hint:"Frame = the list the sample comes from.",steps:[{title:"Key idea",body:"Book p. 141: the frame is an identifiable list that **represents** the population."},{title:"Apply to the stem",body:"Its example: licensed drivers may represent the adult public better than registered voters."}],final:"Frame represents the population → answer **C**",whyWrong:["Incorrect — a frame represents the population; gaps between them are a source of bias.","Incorrect — the measured subset is the sample.","","Incorrect — large populations are exactly when a frame is needed to draw a sample."],bookRef:"Book p. 141"},{id:"sv-2-809",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which statement about parameters and statistics is CORRECT?",options:["A parameter is calculated from a sample and estimates a statistic","Parameters are written with Latin letters such as s","N is the symbol for the sample size","A statistic is calculated from a sample and estimates a parameter"],answer:3,hint:"Sample → Statistic; Population → Parameter.",steps:[{title:"Key idea",body:"Statistics (x̄, s, p, n) come from samples and estimate parameters (μ, σ, P, N)."},{title:"Eliminate look-alikes",body:"The other options swap the roles or the symbols."}],final:"Statistic estimates parameter → answer **D**",whyWrong:["Incorrect — reversed: parameters belong to populations.","Incorrect — Latin letters (x̄, s) are sample statistics; parameters use Greek letters.","Incorrect — N is the population size; n is the sample size.",""],bookRef:"Book pp. 140–141"},{id:"sv-2-810",phase:2,topic:"2.2.1",qtype:"concept",difficulty:3,stem:"Which statement about the scales of measurement is CORRECT?",options:['Only ratio data support statements such as "twice as much"',"Interval data have a true zero","The differences between ordinal values are equal","Nominal values can be ranked from best to worst"],answer:0,hint:"Which scale has a true zero?",steps:[{title:"Key idea",body:"Ratio data have a true zero, so division and 'twice as much' make sense."},{title:"Eliminate look-alikes",body:"Each wrong option gives a scale a property it lacks."}],final:"Ratio → 'twice as much' → answer **A**",whyWrong:["","Incorrect — interval data have no true zero (e.g. IQ, °C).","Incorrect — ordinal differences have no exact meaning.","Incorrect — nominal values are labels with no order."],bookRef:"Book pp. 144–145"},{id:"sv-2-811",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which statement about converting attribute data into continuous data is CORRECT?",options:["The number of scratches is more useful than total scratch length","Total scratch length is more useful than the number of scratches","Attribute data can never be turned into a more useful form","Converting data to a rate makes it less informative"],answer:1,hint:"The book's three 'which is more useful?' examples.",steps:[{title:"Key idea",body:"Book p. 146: 15 scratches vs **total scratch length 9.25**; 22 foreign materials vs 2.5 per square inch; 200 defects vs 25 per hour."},{title:"Apply to the stem",body:"The measured amount or rate is the more useful form."}],final:"Measured length beats count → answer **B**",whyWrong:["Incorrect — reversed: the book prefers the measured length.","","Incorrect — the book shows rates and measured amounts as better forms.","Incorrect — a rate such as defects per hour lets shifts of different length be compared."],bookRef:"Book p. 146"},{id:"sv-2-812",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which statement about the role of statistics in Six Sigma is CORRECT?",options:["It aims to turn every team member into a statistician","It replaces process knowledge with formulas","It aims to make people excellent problem solvers, not statisticians","It is used only by Black Belts"],answer:2,hint:"What does Six Sigma want people to become?",steps:[{title:"Key idea",body:"Book p. 140: Six Sigma does not turn people into statisticians; it makes them **excellent problem solvers** using the right techniques."},{title:"Eliminate look-alikes",body:"The other options overstate or narrow the role of statistics."}],final:"Problem solvers, not statisticians → answer **C**",whyWrong:["Incorrect — the book says the opposite: problem solvers, not statisticians.","Incorrect — statistics refines data; process knowledge is still needed to act on it.","","Incorrect — Green Belts and teams use basic statistics throughout DMAIC."],bookRef:"Book p. 140"},{id:"sv-2-813",phase:2,topic:"2.2.1",qtype:"statements",difficulty:2,stem:`Which statements about data types are CORRECT?

1. Pass/fail results are continuous data.
2. The number of defects on a unit is discrete data.
3. Feed rate is continuous data.
4. Customer returns can be meaningfully subdivided.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Measured → continuous; counted → discrete; two values → attribute.",steps:[{title:"Key idea",body:"Feed rate is measured (continuous); number of defects is a count (discrete); pass/fail is attribute."},{title:"Apply to the stem",body:"Statements 2 and 3 are true."}],final:"2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: pass/fail is attribute data.","","Incorrect — statement 3 is true, but returns are counts and cannot be meaningfully split.","Incorrect — both are false: pass/fail is attribute, and returns are discrete counts."],bookRef:"Book pp. 142–143"},{id:"sv-2-814",phase:2,topic:"2.2.1",qtype:"statements",difficulty:2,stem:`Which statements about populations and samples are CORRECT?

1. A population is all the items that have the property of interest.
2. A sample is usually larger than its frame.
3. Parameters describe samples.
4. Sampling saves time, money and resources.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Population → frame → sample, getting smaller.",steps:[{title:"Key idea",body:"The population is all items of interest; a well-drawn sample gives a good inference for **much less time, money and resources**."},{title:"Apply to the stem",body:"Statements 1 and 4 are true."}],final:"1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: a sample is a subset drawn from the frame.","Incorrect — both are false: the sample is smaller, and parameters describe populations.","Incorrect — statement 4 is true, but parameters describe populations, not samples.",""],bookRef:"Book p. 141"},{id:"sv-2-815",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

[?] data are measured on a scale where decimals are meaningful, such as time, pressure or conveyor speed.`,options:["Attribute","Continuous","Discrete","Nominal"],answer:1,hint:"Can the value be meaningfully subdivided?",steps:[{title:"Key idea",body:"Book p. 143: **continuous** data are measured on a scale; decimals are meaningful."},{title:"Apply to the stem",body:"Time, pressure and conveyor speed are the book's continuous examples."}],final:"Continuous → answer **B**",whyWrong:["Incorrect — attribute data take only two values, such as pass or fail.","","Incorrect — discrete data are whole-number counts that cannot be meaningfully split.","Incorrect — nominal is a scale of labels, not measured values."],bookRef:"Book p. 143"},{id:"sv-2-816",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Car size categories from subcompact to luxury are an example of [?] data.`,options:["interval","nominal","ordinal","ratio"],answer:2,hint:"Ordered, but are the gaps exact?",steps:[{title:"Key idea",body:"Book p. 144 uses car size (subcompact … luxury) as its **ordinal** example."},{title:"Apply to the stem",body:"The classes are ordered, but the gaps between them have no exact meaning."}],final:"ordinal → answer **C**",whyWrong:["Incorrect — interval data need meaningful equal differences, which size classes do not have.","Incorrect — the size classes have a clear order, so they are more than labels.","","Incorrect — ratio data need a true zero and meaningful division."],bookRef:"Book p. 144"},{id:"sv-2-817",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word(s) in the following sentence.

The book compares raw data to [?]: of little use on its own, but valuable once it is refined into information.`,options:["crude oil","gold ore","raw cotton","wheat"],answer:0,hint:"Refined into fuel, medicine and food products.",steps:[{title:"Key idea",body:"Book p. 139: data are like **crude oil**: not very useful until refined."},{title:"Apply to the stem",body:"Statistics is the refinery that turns data into information and knowledge."}],final:"crude oil → answer **A**",whyWrong:["","Incorrect — the book's image is crude oil refined into fuel, medicine and food products.","Incorrect — the book does not use cotton; its analogy is crude oil.","Incorrect — the book does not use wheat; its analogy is crude oil."],bookRef:"Book p. 139"},{id:"sv-2-818",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a purpose of basic statistics listed in the book?",options:["To give a numerical summary of the data","To provide a basis for inferences about the future","To give a common language for describing processes","To prove the root cause of a problem"],answer:3,hint:"Four purposes: summary, inference, capability, common language.",steps:[{title:"Key idea",body:"Book p. 139: summary, basis for inference, foundation for capability, common language."},{title:"Apply to the stem",body:"Proving root causes is the job of Analyze tools, not a listed purpose of basic statistics."}],final:"Root-cause proof is not listed → answer **D**",whyWrong:["Incorrect — a numerical summary is one of the book's four purposes.","Incorrect — a basis for inferences is one of the book's four purposes.","Incorrect — a common language is one of the book's four purposes.",""],bookRef:"Book p. 139"},{id:"sv-2-819",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:2,stem:"Which symbol is NOT a population parameter?",options:["s","μ","N","σ"],answer:0,hint:"Greek letters and capital N belong to the population.",steps:[{title:"Key idea",body:"Population: μ, σ, σ², P, N. Sample: x̄, s, s², p, n."},{title:"Apply to the stem",body:"s is the sample standard deviation, so it is a statistic."}],final:"s is a statistic → answer **A**",whyWrong:["","Incorrect — μ is the population mean.","Incorrect — N is the population size.","Incorrect — σ is the population standard deviation."],bookRef:"Book p. 141"},{id:"sv-2-820",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:2,stem:"Which of these is NOT ordinal data?",options:["Service rating: poor, good, excellent","Country of birth","T-shirt size: small, medium, large","Incident priority: P1, P2, P3, P4"],answer:1,hint:"Is there a natural order?",steps:[{title:"Key idea",body:"Ordinal data have an order; nominal data are labels only."},{title:"Apply to the stem",body:"Country of birth has no order, so it is nominal (a book example)."}],final:"Country of birth = nominal → answer **B**",whyWrong:["Incorrect — poor/good/excellent is ordered, so it is ordinal.","","Incorrect — small/medium/large is ordered, so it is ordinal.","Incorrect — priority levels are ordered, so they are ordinal."],bookRef:"Book p. 144"},{id:"sv-2-821",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a way of turning attribute data into more useful data, in the book's sense?",options:["Recording total scratch length instead of the number of scratches","Recording defects per square inch instead of total defects","Recording each unit only as pass or fail","Recording defects per hour instead of total defects"],answer:2,hint:"Which option moves to less information?",steps:[{title:"Key idea",body:"The book converts counts into **measured amounts or rates**."},{title:"Apply to the stem",body:"Pass/fail is binary attribute data, the lowest level, so it is a step backwards."}],final:"Pass/fail is a step back → answer **C**",whyWrong:["Incorrect — total scratch length is one of the book's examples of a better form.","Incorrect — defects per square inch is one of the book's examples of a better form.","","Incorrect — defects per hour is one of the book's examples of a better form."],bookRef:"Book p. 146"},{id:"sv-2-822",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:1,stem:"A Black Belt wants to know the mean resolution time of **all P2 incidents closed in Q3** (about 12,000). She randomly selects 200 of them from the ticket system. What is the population?",options:["The 200 incidents selected","The ticket system's export of Q3 incidents","The mean resolution time of the 200 incidents","All P2 incidents closed in Q3"],answer:3,hint:"Population = everything the question is about.",steps:[{title:"Key idea",body:"The population is all items with the property of interest."},{title:"Apply to the stem",body:"Her question is about all P2 incidents closed in Q3."}],final:"All Q3 P2 incidents → answer **D**",whyWrong:["Incorrect — the 200 selected incidents are the sample.","Incorrect — the system export is the frame the sample is drawn from.","Incorrect — the mean of the 200 incidents is a statistic.",""],bookRef:"Book p. 141"},{id:"sv-2-823",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:3,stem:"A team estimates average repair time from a vendor's exported ticket list. The export leaves out every ticket that was reopened. The Black Belt suggests doubling the sample size from the same export. What will this MOST likely achieve?",options:["A more precise estimate of a biased number","An unbiased estimate of the population","A frame that now includes the reopened tickets","No change in precision or bias"],answer:0,hint:"Sample size and frame quality fix different problems.",steps:[{title:"Key idea",body:"A frame must represent the population. More data from a biased frame shrinks random error only."},{title:"Apply to the stem",body:"The result is a sharper estimate of the wrong value."}],final:"Precise but still biased → answer **A**",whyWrong:["","Incorrect — a bigger sample cannot fix a frame that leaves out part of the population.","Incorrect — the frame is unchanged; reopened tickets are still missing.","Incorrect — a larger sample does improve precision, even though bias remains."],bookRef:"Book p. 141",trap:"Precision is not accuracy."},{id:"sv-2-824",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:1,stem:"After each installation, a supervisor records whether the job passed the first-time-right check: **Yes** or **No**. What type of data is this?",options:["Attribute","Continuous","Discrete","Ratio"],answer:0,hint:"How many values can the record take?",steps:[{title:"Key idea",body:"Attribute data are binary: Yes/No, Pass/Fail."},{title:"Apply to the stem",body:"First-time-right Yes/No is attribute data."}],final:"Yes/No → attribute → answer **A**",whyWrong:["","Incorrect — nothing is measured on a scale; there are only two values.","Incorrect — discrete data are counts; a single yes/no is a two-value attribute.","Incorrect — ratio is a scale of measurement with a true zero, not a yes/no record."],bookRef:"Book p. 142"},{id:"sv-2-825",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:2,stem:"A service desk classifies incidents as **P1, P2, P3 or P4**, where P1 is the most urgent. On which scale of measurement are these priority codes?",options:["Interval","Nominal","Ordinal","Ratio"],answer:2,hint:"Ranked, but with no defined gaps.",steps:[{title:"Key idea",body:"Ordinal = ordered categories whose differences have no exact meaning."},{title:"Apply to the stem",body:"P1–P4 are ranked by urgency, but 'P2 minus P1' means nothing."}],final:"Priority codes are ordinal → answer **C**",whyWrong:["Incorrect — the gap between P1 and P2 is not a defined amount.","Incorrect — the codes are more than labels; they are ranked.","","Incorrect — there is no true zero and no meaningful division."],bookRef:"Book p. 144"},{id:"sv-2-826",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:3,stem:'Regions are coded **1 = North, 2 = Centre, 3 = South** in a worksheet. An analyst reports that "the average region of complaints is 1.8". What is wrong with this?',options:["Region is ordinal, so the median should have been used","Region is nominal, so an average of the codes has no meaning","Region is interval, so the mean must be rounded to a whole number","Region is continuous, so a standard deviation is also needed"],answer:1,hint:"Numbers used as names are still names.",steps:[{title:"Key idea",body:"The scale depends on what the numbers mean, not on how they are stored."},{title:"Apply to the stem",body:"The codes only name regions (nominal), so only counts or the mode make sense."}],final:"Nominal codes cannot be averaged → answer **B**",whyWrong:["Incorrect — the regions have no natural order, so they are not ordinal.","","Incorrect — the codes are labels; differences between them have no meaning.","Incorrect — region is a label, not a measurement."],bookRef:"Book p. 144",trap:"Numeric codes ≠ numeric data."},{id:"sv-2-827",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:2,stem:"A panel line counts dents on each panel, but panel sizes vary widely from order to order. The team wants to compare dent levels between orders. Which form of the data is MOST useful?",options:["Total dents per order","Whether each panel has any dents","Dents per square metre of panel","The largest panel in each order"],answer:2,hint:"Turn the count into a rate.",steps:[{title:"Key idea",body:'Book p. 146: "2.5 foreign materials per square inch" is more useful than "22 foreign materials".'},{title:"Apply to the stem",body:"Dents per square metre allows a fair comparison across panel sizes."}],final:"Express as a rate per area → answer **C**",whyWrong:["Incorrect — totals are distorted by panel size and order volume.","Incorrect — a yes/no per panel loses information, the opposite of the book's advice.","","Incorrect — panel size alone says nothing about dent level."],bookRef:"Book p. 146"},{id:"sv-2-828",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:1,stem:`In a review meeting a manager says: *"I feel the night shift makes more errors, so let's retrain them."* No error data have been examined. Which basic-statistics principle should the Black Belt raise?`,options:["Opinions are valid if the manager is experienced","Retraining should always come before measuring","Night shifts should be excluded from the sample","Decisions should be based on data, not on opinion"],answer:3,hint:'"I think", "I feel", "in my opinion".',steps:[{title:"Key idea",body:"The book's aim: decide on **data**, not on feelings or opinion."},{title:"Apply to the stem",body:"Collect error data by shift before choosing a solution."}],final:"Data before decisions → answer **D**",whyWrong:["Incorrect — experience suggests ideas to test; it does not replace data.","Incorrect — measuring first shows whether a problem exists at all.","Incorrect — excluding a shift would bias the data, not fix the decision.",""],bookRef:"Book p. 142"},{id:"sv-2-829",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:1,stem:"A Black Belt receives a new dataset with several variables for the Measure phase. What should she do FIRST before choosing graphs or tests?",options:["Identify the data type of each variable","Run a hypothesis test on every variable","Calculate process capability for each variable","Remove all values that look unusual"],answer:0,hint:"The first step in refining data.",steps:[{title:"Key idea",body:"Book p. 142: the first step in refining data is to know what **type** it is."},{title:"Apply to the stem",body:"Data type decides which graphs and tests are allowed later."}],final:"Classify data types first → answer **A**",whyWrong:["","Incorrect — the test depends on the data type, so the type must be known first.","Incorrect — capability also depends on the data type and on a stable process.","Incorrect — unusual values are investigated, not deleted, and only after knowing the data."],bookRef:"Book p. 142"},{id:"sv-2-830",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:2,stem:`A team's data collection plan defines the survey population simply as **"customers"**. What is the BEST action for the Black Belt?`,options:["Keep the definition broad so that more customers can be sampled","Define the population precisely, for example all postpaid customers who contacted support in September","Skip the definition and let the frame decide who is included","Replace the population with the sample size required"],answer:1,hint:`The book's example: "all trades completed in 2001".`,steps:[{title:"Key idea",body:"Book p. 141: define the population **carefully**, with clear scope and time period."},{title:"Apply to the stem",body:"A precise definition lets the team pick a frame that represents it."}],final:"Define the population precisely → answer **B**",whyWrong:["Incorrect — a broad, vague definition makes the inference unclear and the frame hard to check.","","Incorrect — the frame must represent a defined population, not replace it.","Incorrect — sample size and population are different things."],bookRef:"Book p. 141"},{id:"sv-2-831",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:3,stem:'Customers rate a service from 1 (poor) to 5 (excellent). A Black Belt writes that "customers who gave a 4 are twice as satisfied as those who gave a 2". Was this an appropriate conclusion?',options:["Yes, because the ratings are numbers and can be divided","Yes, because a rating scale has a true zero","No, because the ratings are ordinal and their differences have no exact meaning","No, because the ratings are nominal labels with no order"],answer:2,hint:"Which scale allows 'twice as'?",steps:[{title:"Key idea",body:"Ratings are **ordinal**: ordered, but the gaps are not exact and there is no true zero."},{title:"Apply to the stem",body:"'Twice as satisfied' needs a ratio scale."}],final:"Ordinal → no ratio claims → answer **C**",whyWrong:["Incorrect — numeric codes do not make ordered ratings ratio data.","Incorrect — the scale starts at 1 and has no true zero.","","Incorrect — the ratings are ordered, so they are ordinal, not nominal."],bookRef:"Book pp. 144–145"},{id:"sv-2-832",phase:2,topic:"2.2.1",qtype:"output",difficulty:3,stem:`A Black Belt randomly sampled tickets from Q3 and ran Minitab:

\`\`\`
Descriptive Statistics: ResolveHrs
Variable    N    Mean   StDev   Minimum  Maximum
ResolveHrs  150  3.42   1.05    0.60     7.80
\`\`\`

Which statement about this output is CORRECT?`,options:["The Mean and StDev are the population parameters μ and σ","N = 150 is the number of tickets in the population","The output shows the data are attribute data","The Mean and StDev are statistics that estimate the population μ and σ"],answer:3,hint:"Sample in → statistics out.",steps:[{title:"Key idea",body:"Values computed from a sample are **statistics** (x̄, s) that estimate parameters (μ, σ)."},{title:"Apply to the stem",body:"The tickets were a random sample, so Mean = x̄ and StDev = s."}],final:"Sample values are statistics → answer **D**",whyWrong:["Incorrect — values from a sample are statistics, not parameters.","Incorrect — N here is the sample size of 150, not the Q3 total.","Incorrect — resolution hours are measured time, so the data are continuous.",""],bookRef:"Book pp. 140–141"},{id:"sv-2-833",phase:2,topic:"2.2.1",qtype:"output",difficulty:2,stem:`Minitab tally of complaint regions:

\`\`\`
Tally for Discrete Variables: Region
Region   Count  Percent
Centre     212    42.40
North      168    33.60
South      120    24.00
N=         500
\`\`\`

Which summary suits this variable best?`,options:["Counts and the most frequent category, because Region is nominal","The mean region, because the counts are numeric","The median region, because the categories are ordered","The standard deviation of the percentages, because they are continuous"],answer:0,hint:"What can you do with labels?",steps:[{title:"Key idea",body:"Region is a **nominal** variable: labels with no order."},{title:"Apply to the stem",body:"Counts, percentages and the most frequent category (Centre) are the right summary."}],final:"Nominal → counts and mode → answer **A**",whyWrong:["","Incorrect — region names have no numeric value to average.","Incorrect — Centre, North and South have no natural order.","Incorrect — the percentages summarise counts of labels; they are not measurements."],bookRef:"Book p. 144"},{id:"sv-2-834",phase:2,topic:"2.2.1",qtype:"output",difficulty:3,stem:`A data dictionary for a call-centre project:

\`\`\`
Field          Example values
Priority       P1, P2, P3
Queue          Billing, Technical, Sales
HandleSec      0 … 1840
RoomTempC      19.5 … 24.0
\`\`\`

For which field is a statement such as "call A took twice as long as call B" meaningful?`,options:["HandleSec","Priority","Queue","RoomTempC"],answer:0,hint:"Ratios need a true zero.",steps:[{title:"Key idea",body:"Only **ratio** data support 'twice as'. Time has a true zero (0 s = no time)."},{title:"Apply to the stem",body:"HandleSec is ratio; the others are ordinal, nominal and interval."}],final:"HandleSec is ratio → answer **A**",whyWrong:["","Incorrect — priority is ordinal: ordered, but no meaningful ratios.","Incorrect — queue is nominal: labels only.","Incorrect — °C is interval: zero is arbitrary, so ratios have no meaning."],bookRef:"Book pp. 144–145"},{id:"sv-2-835",phase:2,topic:"2.2.1",qtype:"output",difficulty:3,stem:`A sampling plan summary:

\`\`\`
Population : all active broadband accounts      10,000
Frame      : billing-system extract              9,400
             (excludes accounts migrated from the old platform)
Sample     : simple random sample from frame       300
\`\`\`

Which statement is CORRECT?`,options:["The sample of 300 is too small to represent any population","Migrated accounts cannot be selected, so the frame may not represent the population","The frame and the population are the same, so no bias is possible","Random selection from the frame removes any bias from the missing accounts"],answer:1,hint:"Compare the frame line with the population line.",steps:[{title:"Key idea",body:"A frame should **represent** the population; anything missing from it can never be sampled."},{title:"Apply to the stem",body:"The extract excludes migrated accounts, so their behaviour is not represented."}],final:"Frame coverage gap → answer **B**",whyWrong:["Incorrect — the output gives no basis to call 300 too small; the issue is coverage.","","Incorrect — the output shows the frame excludes some accounts.","Incorrect — randomness inside the frame cannot reach accounts outside it."],bookRef:"Book p. 141"},{id:"sv-2-836",phase:2,topic:"2.2.1",qtype:"output",difficulty:3,stem:`Minitab output for the number of solder defects found on each board:

\`\`\`
Descriptive Statistics: DefectsPerBoard
Variable          N    Mean   Minimum  Maximum
DefectsPerBoard   80   2.31   0        7
\`\`\`

Which statement is CORRECT?`,options:["The data are continuous because the mean is 2.31","The data are attribute data because the minimum is 0","The data are discrete counts, even though the mean has decimals","The data are ordinal because the values run from 0 to 7"],answer:2,hint:"Classify each value, not the summary.",steps:[{title:"Key idea",body:"Each board's value is a **count** of defects: a whole number that cannot be meaningfully split."},{title:"Apply to the stem",body:"A decimal mean of counts does not make the data continuous."}],final:"Counts stay discrete → answer **C**",whyWrong:["Incorrect — a summary can have decimals while each value is a whole count.","Incorrect — attribute data have only two values; here there are eight possible counts.","","Incorrect — a count of defects is not an ordered rating; it is a count."],bookRef:"Book p. 143",trap:"Judge the data type by the raw values, not the mean."},{id:"sv-2-837",phase:2,topic:"2.2.1",qtype:"output",difficulty:2,stem:`A Black Belt compared two ways of recording the same solder joints:

\`\`\`
Measure option                 Sample needed to detect the shift
Pass/fail per joint            400 joints
Pull strength (newtons)         35 joints
\`\`\`

Which conclusion does this table support?`,options:["Attribute data need a much smaller sample to detect the same change","Both options carry the same amount of information","Pass/fail data should be chosen because they are simpler to analyse","Continuous data need a much smaller sample to detect the same change"],answer:3,hint:"Read the sample column.",steps:[{title:"Key idea",body:"Continuous data show how far each unit is from target, so they need **smaller samples**."},{title:"Apply to the stem",body:"The table reads 35 joints for pull strength against 400 for pass/fail."}],final:"Continuous needs fewer samples → answer **D**",whyWrong:["Incorrect — reversed: the table shows pass/fail needs far more joints.","Incorrect — the very different sample sizes show the information differs.","Incorrect — simplicity does not outweigh the much larger sample pass/fail needs.",""],bookRef:"Book p. 146"},{id:"sv-2-838",phase:2,topic:"2.2.1",qtype:"true-false",difficulty:2,stem:"Temperature measured in °C is on a ratio scale because it can take decimal values. True or False?",options:["True","False"],answer:1,hint:"What does a ratio scale need?",steps:[{title:"Key idea",body:"A ratio scale needs a **true zero**; °C has an arbitrary zero."},{title:"Apply to the stem",body:"So °C is interval: 20 °C is not twice as hot as 10 °C. The statement is false."}],final:"False → answer **False**",whyWrong:["Incorrect — decimals do not make a scale ratio; 0 °C is not 'no heat', so °C is interval.",""],bookRef:"Book p. 145"},{id:"sv-2-839",phase:2,topic:"2.2.1",qtype:"sequence",difficulty:1,stem:`Put these steps in the order a Black Belt follows to draw a conclusion about a population.

- **P** Draw a sample from the frame
- **Q** Define the population of interest
- **R** Make an inference about the population
- **S** Identify a frame that represents the population`,options:["Q → S → P → R","S → Q → P → R","Q → P → S → R","P → Q → S → R"],answer:0,hint:"Whole → list → subset → conclusion.",steps:[{title:"Key idea",body:"Population (what we want to know about) → frame (the list) → sample (the subset) → inference."},{title:"Apply to the stem",body:"So Q, S, P, R."}],final:"Q → S → P → R → answer **A**",whyWrong:["","Incorrect — the frame is chosen to represent a population that must be defined first.","Incorrect — a sample is drawn from the frame, so the frame comes first.","Incorrect — sampling before defining the population gives a sample of an unknown group."],bookRef:"Book p. 141"},{id:"sv-2-840",phase:2,topic:"2.2.1",qtype:"sequence",difficulty:2,stem:"Order these data types from the **least** information to the **most** information, as the book describes them.",options:["Discrete → attribute → continuous","Attribute → discrete → continuous","Continuous → discrete → attribute","Attribute → continuous → discrete"],answer:1,hint:"Yes/no, then counts, then measurements.",steps:[{title:"Key idea",body:"Attribute is the lowest level; counts add 'how many'; measurements add 'how much' on a scale."},{title:"Apply to the stem",body:"So attribute → discrete → continuous."}],final:"Attribute → discrete → continuous → answer **B**",whyWrong:["Incorrect — a count carries more information than a single yes/no.","","Incorrect — reversed: continuous carries the most information.","Incorrect — continuous data, not counts, carry the most information."],bookRef:"Book pp. 142–146"}];export{e as items};
